import { z } from "zod";
import { revalidatePath } from "next/cache";
import { requireRole } from "@/lib/auth";
import { fail, handleRouteError, ok } from "@/lib/api";
import { createAdminClient } from "@/lib/supabase/admin";
import { generateTemporaryPassword, provisionAuthUser, writeUserCreationAudit } from "@/lib/onboarding/user-provisioning";

const schema = z.object({
  action: z.enum(["approve_lead", "request_contact", "reject_lead", "mark_contacted", "mark_not_relevant", "resend_credentials", "approve_final_profile", "activate_after_payment", "request_corrections", "suspend", "archive"]),
  lead_id: z.string().uuid().optional(),
  garden_id: z.string().uuid().optional(),
  note: z.string().optional(),
  manager_name: z.string().optional(),
  manager_phone: z.string().optional(),
  manager_email: z.string().email().optional().or(z.literal(""))
});

function loginUrl() {
  return process.env.NEXT_PUBLIC_APP_URL || process.env.APP_URL || "http://localhost:3000";
}

function canStoreTemporaryPasswordInMockLog() {
  return process.env.NODE_ENV !== "production" || process.env.NEXT_PUBLIC_SANDBOX_MODE === "true";
}

function credentialVariables(temporaryPassword: string) {
  const mockLogAllowed = canStoreTemporaryPasswordInMockLog();
  return {
    temporary_password: mockLogAllowed ? temporaryPassword : "[redacted]",
    temporary_password_redacted: !mockLogAllowed
  };
}

async function insertCredentialCommunicationLogs(admin: ReturnType<typeof createAdminClient>, input: {
  gardenId: string;
  managerId: string;
  username: string;
  temporaryPassword: string;
  gardenName: string;
  phone?: string | null;
}) {
  const now = new Date().toISOString();
  const messagePreview = `כניסה לגן בטוח עבור ${input.gardenName}. שם משתמש: ${input.username}. יש להשלים פרופיל גן לאחר התחברות.`;
  const passwordVariables = credentialVariables(input.temporaryPassword);
  await Promise.all([
    admin.from("email_delivery_logs" as any).insert({
      recipient_profile_id: input.managerId,
      kindergarten_id: input.gardenId,
      category: "onboarding",
      recipient_email: input.username,
      subject_preview: "פרטי כניסה לגן בטוח",
      message_preview: messagePreview,
      status: "queued",
      provider: "mock",
      sent_at: null,
      metadata: {
        login_url: `${loginUrl()}/login`,
        includes_temporary_password: canStoreTemporaryPasswordInMockLog(),
        temporary_password_redacted: !canStoreTemporaryPasswordInMockLog(),
        password_delivery: "provider_payload_only"
      }
    }),
    admin.from("whatsapp_message_logs" as any).insert({
      recipient_profile_id: input.managerId,
      kindergarten_id: input.gardenId,
      event_type: "registration",
      status: "queued",
      provider: "mock_whatsapp",
      template_name: "kindergarten_manager_credentials",
      template_language: "he",
      variables: {
        login_url: `${loginUrl()}/login`,
        username: input.username,
        ...passwordVariables,
        garden_name: input.gardenName
      },
      queued_at: now,
      metadata: { source: "kindergarten_approval_flow" }
    }),
    admin.from("sms_message_logs" as any).insert({
      recipient_profile_id: input.managerId,
      kindergarten_id: input.gardenId,
      event_type: "registration_verification",
      recipient_phone: input.phone ?? null,
      masked_phone: input.phone ? `***${String(input.phone).slice(-4)}` : null,
      message_preview: "פרטי כניסה לגן בטוח נשלחו למנהלת. יש להשלים פרופיל גן.",
      status: "queued",
      provider: "mock_sms",
      variables: {
        login_url: `${loginUrl()}/login`,
        username: input.username,
        ...passwordVariables,
        garden_name: input.gardenName
      },
      queued_at: now,
      metadata: { source: "kindergarten_approval_flow", readiness_only: true }
    })
  ]);
}

async function latestCredentials(admin: ReturnType<typeof createAdminClient>, userId: string) {
  const { data } = await admin
    .from("generated_credentials" as any)
    .select("username, temporary_password")
    .eq("user_id", userId)
    .is("password_changed_at", null)
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();
  return data as any;
}

export async function POST(request: Request) {
  try {
    const { profile } = await requireRole(["admin"]);
    const payload = schema.parse(await request.json());
    const admin = createAdminClient();
    const now = new Date().toISOString();

    if (payload.action === "request_contact" || payload.action === "reject_lead" || payload.action === "mark_contacted" || payload.action === "mark_not_relevant") {
      if (!payload.lead_id) return fail("חסר ליד לעדכון", 422);
      const nextStatus =
        payload.action === "request_contact" ? "lead_review" :
        payload.action === "mark_contacted" ? "contacted" :
        payload.action === "mark_not_relevant" ? "not_relevant" :
        "archived";
      const { data: existingLead } = await admin.from("leads" as any).select("notes").eq("id", payload.lead_id).eq("lead_type", "garden").maybeSingle();
      const note = payload.note?.trim();
      const nextNotes = note ? [existingLead?.notes, `[${new Date().toLocaleDateString("he-IL")}] ${note}`].filter(Boolean).join("\n") : existingLead?.notes;
      const { data: lead, error: leadError } = await admin
        .from("leads" as any)
        .update({ status: nextStatus, notes: nextNotes })
        .eq("id", payload.lead_id)
        .eq("lead_type", "garden")
        .select("id")
        .maybeSingle();
      if (leadError || !lead) return fail("לא נמצא ליד גן לעדכון", 404);
      await admin.from("audit_logs" as any).insert({
        actor_id: profile.id,
        actor_role: "admin",
        performed_by_user: profile.id,
        performed_by_role: "admin",
        entity_type: "leads",
        entity_id: payload.lead_id,
        action: `kindergarten_${payload.action}`,
        after_data: { status: nextStatus, note: payload.note ?? null }
      });
      revalidatePath("/dashboard/admin/leads");
      return ok({ lead_id: payload.lead_id, status: nextStatus });
    }

    if (payload.action === "approve_lead") {
      if (!payload.lead_id) return fail("חסר ליד לאישור", 422);
      const { data: lead, error: leadError } = await admin
        .from("leads" as any)
        .select("*")
        .eq("id", payload.lead_id)
        .eq("lead_type", "garden")
        .maybeSingle();
      if (leadError || !lead) return fail("לא נמצא ליד גן לאישור", 404);
      if (lead.converted_entity_id) return fail("הליד כבר חובר לגן", 409);

      const qualification = (lead.qualification && typeof lead.qualification === "object" ? lead.qualification : {}) as Record<string, unknown>;
      const isParentOriginLead = lead.source === "parent_request";
      const managerName = payload.manager_name?.trim() || String(qualification.manager_name ?? "") || lead.manager_name || lead.owner_name || lead.garden_name || "מנהלת הגן";
      const managerEmail = payload.manager_email?.trim() || String(qualification.manager_email ?? "") || (isParentOriginLead ? "" : lead.email) || undefined;
      const managerPhone = payload.manager_phone?.trim() || String(qualification.manager_phone ?? "") || (isParentOriginLead ? "" : lead.phone) || undefined;
      if (isParentOriginLead && !managerEmail && !managerPhone) {
        return fail("צריך לצרף טלפון או מייל של מנהלת הגן לפני המרה לרישום", 422);
      }
      const temporaryPassword = generateTemporaryPassword();
      const manager = await provisionAuthUser({
        role: "manager",
        fullName: managerName,
        email: managerEmail,
        phone: managerPhone,
        temporaryPassword,
        createdBy: profile.id,
        conflictField: "manager_email"
      });

      const { data: garden, error: gardenError } = await admin.from("gardens" as any).insert({
        name: lead.garden_name || "גן חדש",
        city: lead.city || "לא צוינה",
        address: lead.address || null,
        phone: managerPhone || lead.phone || null,
        email: manager.oneTimeCredentials.email,
        manager_id: manager.user.id,
        owner_name: lead.owner_name || managerName,
        status: "pending",
        approval_flow_status: "admin_approved",
        final_approval_status: "activation_in_progress",
        onboarding_status: "activation_in_progress",
        public_profile_enabled: false,
        children_capacity: Number(lead.capacity ?? 0),
        current_children_count: Number(lead.children_count ?? 0),
        staff_count: Number(lead.staff_count ?? 0),
        ages: Array.isArray(lead.age_groups) ? lead.age_groups : [],
        safe_status: "pending_review",
        eligible_for_safe_status: false,
        credentials_sent_at: now,
        admin_correction_note: null
      }).select("*").single();
      if (gardenError || !garden) {
        await admin.auth.admin.deleteUser(manager.user.id);
        return fail("לא ניתן ליצור גן ממתין להשלמה: " + (gardenError?.message ?? "שגיאה לא ידועה"), 400);
      }

      const { error: profileError } = await admin.from("profiles" as any).update({ garden_id: garden.id }).eq("id", manager.user.id);
      if (profileError) {
        await admin.from("gardens" as any).delete().eq("id", garden.id);
        await admin.auth.admin.deleteUser(manager.user.id);
        return fail("נוצר משתמש אך שיוך הגן נכשל", 400);
      }

      await Promise.all([
        admin.from("leads" as any).update({
          status: "credentials_sent",
          manager_name: managerName,
          phone: isParentOriginLead ? lead.phone : (managerPhone || lead.phone),
          email: isParentOriginLead ? lead.email : (managerEmail || lead.email),
          funnel_stage: "converted",
          qualification: {
            ...qualification,
            manager_name: managerName,
            manager_phone: managerPhone ?? null,
            manager_email: managerEmail ?? null,
            converted_from_source: lead.source ?? null,
            admin_conversion_note: payload.note?.trim() || null
          },
          converted_entity_id: garden.id,
          converted_at: now
        }).eq("id", lead.id),
        admin.from("kindergarten_onboarding_records" as any).upsert({
          lead_id: lead.id,
          garden_id: garden.id,
          manager_id: manager.user.id,
          lifecycle_status: "credentials_sent",
          activation_steps: ["admin_approved"],
          progress_percent: 0,
          credentials_sent_at: now
        }, { onConflict: "garden_id" }),
        admin.from("notifications" as any).insert({
          garden_id: garden.id,
          recipient_id: manager.user.id,
          title: "ברוכה הבאה לגן בטוח",
          body: "התחברי והשלימי את פרופיל הגן כדי לשלוח לאישור.",
          entity_type: "garden",
          entity_id: garden.id,
          severity: "medium",
          metadata: { href: "/onboarding/kindergarten", onboarding: true }
        })
      ]);

      await insertCredentialCommunicationLogs(admin, {
        gardenId: garden.id,
        managerId: manager.user.id,
        username: manager.oneTimeCredentials.username,
        temporaryPassword,
        gardenName: garden.name,
        phone: managerPhone || lead.phone
      });

      await writeUserCreationAudit({
        actorId: profile.id,
        actorRole: "admin",
        gardenId: garden.id,
        entityType: "gardens",
        entityId: garden.id,
        action: "approve_kindergarten_lead_credentials_sent",
        afterData: { lead_id: lead.id, garden_id: garden.id, manager_user_id: manager.user.id }
      });

      revalidatePath("/dashboard/admin/leads");
      return ok({ garden, manager_user_id: manager.user.id, credentials: manager.oneTimeCredentials }, 201);
    }

    if (!payload.garden_id) return fail("חסר גן לעדכון", 422);
    const { data: garden, error: gardenError } = await admin
      .from("gardens" as any)
      .select("id, name, manager_id, status, approval_flow_status, final_approval_status, correction_history")
      .eq("id", payload.garden_id)
      .maybeSingle();
    if (gardenError || !garden) return fail("לא נמצא גן לעדכון", 404);

    if (payload.action === "resend_credentials") {
      if (!garden.manager_id) return fail("לגן אין מנהלת משויכת", 422);
      let credentials = await latestCredentials(admin, garden.manager_id);
      if (!credentials) {
        const temporaryPassword = generateTemporaryPassword();
        const { data: user } = await admin.from("profiles" as any).select("email, username").eq("id", garden.manager_id).maybeSingle();
        credentials = { username: user?.email || user?.username, temporary_password: temporaryPassword };
        await admin.auth.admin.updateUserById(garden.manager_id, { password: temporaryPassword });
        await admin.from("generated_credentials" as any).insert({
          user_id: garden.manager_id,
          username: credentials.username,
          temporary_password: temporaryPassword,
          created_by: profile.id
        });
      }
      await insertCredentialCommunicationLogs(admin, {
        gardenId: garden.id,
        managerId: garden.manager_id,
        username: credentials.username,
        temporaryPassword: credentials.temporary_password,
        gardenName: garden.name
      });
      await Promise.all([
        admin.from("gardens" as any).update({ credentials_sent_at: now, approval_flow_status: "credentials_sent" }).eq("id", garden.id),
        admin.from("kindergarten_onboarding_records" as any).upsert({
          garden_id: garden.id,
          manager_id: garden.manager_id,
          lifecycle_status: "credentials_sent",
          credentials_sent_at: now
        }, { onConflict: "garden_id" })
      ]);
      revalidatePath("/dashboard/admin/leads");
      return ok({ credentials });
    }

    const statusPatch: Record<string, unknown> = { updated_at: now };
    const onboardingPatch: Record<string, unknown> = { updated_at: now };
    if (payload.action === "approve_final_profile") {
      Object.assign(statusPatch, {
        status: "pending",
        approval_flow_status: "payment_pending",
        final_approval_status: "payment_pending",
        onboarding_status: "payment_pending",
        activation_payment_status: "payment_pending",
        final_approved_at: now,
        approved_by: profile.id,
        reviewed_by: profile.id,
        admin_correction_note: null,
        public_profile_enabled: false
      });
      Object.assign(onboardingPatch, {
        lifecycle_status: "payment_pending",
        progress_percent: 100,
        approved_at: now,
        approved_by: profile.id,
        reviewed_by: profile.id,
        payment_status: "payment_pending",
        correction_note: null
      });
    }
    if (payload.action === "activate_after_payment") {
      Object.assign(statusPatch, {
        status: "active",
        approval_flow_status: "active",
        final_approval_status: "active",
        onboarding_status: "completed",
        activation_payment_status: "paid",
        payment_completed_at: now,
        approved_by: profile.id,
        reviewed_by: profile.id,
        admin_correction_note: null,
        public_profile_enabled: true
      });
      Object.assign(onboardingPatch, {
        lifecycle_status: "active",
        progress_percent: 100,
        payment_status: "paid",
        activated_at: now,
        approved_by: profile.id,
        reviewed_by: profile.id,
        correction_note: null
      });
    }
    if (payload.action === "request_corrections") {
      const correction = {
        note: payload.note || "נדרשת השלמה לפני אישור סופי",
        by: profile.id,
        at: now
      };
      Object.assign(statusPatch, {
        status: "pending",
        approval_flow_status: "correction_required",
        final_approval_status: "correction_required",
        onboarding_status: "correction_required",
        reviewed_by: profile.id,
        admin_correction_note: correction.note
      });
      Object.assign(onboardingPatch, {
        lifecycle_status: "correction_required",
        correction_note: correction.note,
        reviewed_by: profile.id
      });
    }
    if (payload.action === "suspend") {
      Object.assign(statusPatch, {
        status: "blocked",
        approval_flow_status: "suspended",
        final_approval_status: "suspended",
        suspended_at: now,
        reviewed_by: profile.id,
        admin_correction_note: payload.note || null,
        public_profile_enabled: false
      });
      Object.assign(onboardingPatch, {
        lifecycle_status: "suspended",
        suspended_at: now,
        reviewed_by: profile.id,
        correction_note: payload.note || null
      });
    }
    if (payload.action === "archive") {
      Object.assign(statusPatch, {
        status: "blocked",
        approval_flow_status: "archived",
        final_approval_status: "archived",
        archived_at: now,
        reviewed_by: profile.id,
        admin_correction_note: payload.note || null,
        public_profile_enabled: false
      });
      Object.assign(onboardingPatch, {
        lifecycle_status: "archived",
        archived_at: now,
        reviewed_by: profile.id,
        correction_note: payload.note || null
      });
    }

    if (payload.action === "request_corrections") {
      const note = payload.note || "נדרשת השלמה לפני אישור סופי";
      const correctionItem = { note, by: profile.id, at: now };
      statusPatch.correction_history = [...((garden as any).correction_history ?? []), correctionItem];
      onboardingPatch.correction_history = [...((garden as any).correction_history ?? []), correctionItem];
    }

    const { error } = await admin.from("gardens" as any).update(statusPatch).eq("id", garden.id);
    if (error) return fail("לא ניתן לעדכן סטטוס גן", 400);
    await admin.from("kindergarten_onboarding_records" as any).upsert({
      garden_id: garden.id,
      manager_id: garden.manager_id,
      ...onboardingPatch
    }, { onConflict: "garden_id" });
    if (payload.action === "approve_final_profile" || payload.action === "activate_after_payment") {
      const onboarding = await admin
        .from("kindergarten_onboarding_records" as any)
        .select("subscription_monthly_amount, profile_data")
        .eq("garden_id", garden.id)
        .maybeSingle();
      const monthlyAmount = Number((onboarding.data as any)?.subscription_monthly_amount ?? (onboarding.data as any)?.profile_data?.subscription_monthly_amount ?? 800);
      const existingSubscription = await admin
        .from("kindergarten_subscriptions" as any)
        .select("id")
        .eq("garden_id", garden.id)
        .in("status", ["active", "trial", "pending_payment", "suspended"])
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      const subscriptionPatch = {
        garden_id: garden.id,
        status: payload.action === "activate_after_payment" ? "active" : "pending_payment",
        billing_status: payload.action === "activate_after_payment" ? "active" : "pending_payment",
        plan_type: "annual",
        billing_cycle: "annual",
        start_date: new Date().toISOString().slice(0, 10),
        renewal_date: new Date(Date.now() + 365 * 86400000).toISOString().slice(0, 10),
        billing_contact_name: garden.name,
        provider: "manual",
        metadata: {
          revenue_stream: "gan_batuach_subscription",
          parent_tuition_separate: true,
          monthly_amount_nis: monthlyAmount,
          annual_amount_nis: monthlyAmount * 12,
          payment_mode: payload.action === "activate_after_payment" ? "manual_or_provider_success" : "pending"
        },
        updated_by: profile.id,
        updated_at: now
      };
      if (existingSubscription.data?.id) {
        await admin.from("kindergarten_subscriptions" as any).update(subscriptionPatch).eq("id", existingSubscription.data.id);
      } else {
        await admin.from("kindergarten_subscriptions" as any).insert({ ...subscriptionPatch, created_by: profile.id });
      }
      if (payload.action === "activate_after_payment") {
        if (garden.manager_id) {
          await Promise.all([
            admin.from("profiles" as any).update({
              active: true,
              self_service_status: "active",
              self_service_approved_at: now,
              self_service_approved_by: profile.id,
              updated_at: now
            }).eq("id", garden.manager_id),
            admin.from("self_service_user_profiles" as any).update({
              status: "active",
              updated_at: now,
              metadata: { activation_source: "admin_payment_or_override", garden_id: garden.id }
            }).eq("profile_id", garden.manager_id)
          ]);
        }
        await admin.from("subscription_payments" as any).insert({
          garden_id: garden.id,
          provider: "manual",
          amount: monthlyAmount,
          currency: "ILS",
          billing_status: "paid",
          paid_at: now,
          payment_method: "admin_manual_activation_or_verified_provider",
          metadata: { revenue_stream: "gan_batuach_subscription", parent_tuition_separate: true },
          created_by: profile.id
        });
      }
    }
    if (garden.manager_id && ["approve_final_profile", "activate_after_payment", "request_corrections", "suspend", "archive"].includes(payload.action)) {
      await admin.from("notifications" as any).insert({
        garden_id: garden.id,
        recipient_id: garden.manager_id,
        title: payload.action === "approve_final_profile" ? "הגן אושר וממתין למנוי" : payload.action === "activate_after_payment" ? "הגן הופעל" : payload.action === "request_corrections" ? "נדרשת השלמה בפרופיל" : "סטטוס הגן עודכן",
        body: payload.action === "approve_final_profile" ? "הבקשה אושרה. יש להשלים מנוי גן בטוח לפני פתיחת הדשבורד המלא." : payload.action === "activate_after_payment" ? "התשלום או override האדמין תועדו. הדשבורד המלא פתוח." : payload.note || "יש הודעה חדשה מהאדמין.",
        entity_type: "garden",
        entity_id: garden.id,
        severity: payload.action === "activate_after_payment" ? "low" : "medium",
        metadata: { href: payload.action === "activate_after_payment" ? "/dashboard/garden" : "/onboarding/kindergarten" }
      });
    }
    await admin.from("audit_logs" as any).insert({
      actor_id: profile.id,
      actor_role: "admin",
      performed_by_user: profile.id,
      performed_by_role: "admin",
      garden_id: garden.id,
      entity_type: "gardens",
      entity_id: garden.id,
      action: `kindergarten_${payload.action}`,
      after_data: statusPatch
    });
    revalidatePath("/dashboard/admin/leads");
    revalidatePath("/dashboard/admin/kindergartens");
    revalidatePath("/dashboard/garden");
    return ok({ garden_id: garden.id, status: statusPatch.status });
  } catch (error) {
    return handleRouteError(error);
  }
}
